// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Minimal ERC-721 for the demo chain.
/// @dev Its Transfer event carries an indexed tokenId, giving the four-topic shape the
///      log decoder uses to tell ERC-721 apart from ERC-20.
contract DemoERC721 {
    string public name;
    string public symbol;
    uint256 public nextTokenId;

    mapping(uint256 => address) public ownerOf;
    mapping(address => uint256) public balanceOf;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    error NotOwner();
    error NotAuthorised();

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
    }

    /// @notice ERC-165, claiming ERC-165 itself and ERC-721.
    /// @dev Here because it is how a reader is *supposed* to tell an NFT apart from a
    ///      fungible token: without it, a lens or an indexer is left guessing from the
    ///      shape of the interface. Deliberately does not claim ERC-721Metadata, which
    ///      this demo does not implement.
    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 || interfaceId == 0x80ac58cd;
    }

    function mint(address to) external returns (uint256 tokenId) {
        tokenId = nextTokenId++;
        ownerOf[tokenId] = to;
        balanceOf[to] += 1;
        emit Transfer(address(0), to, tokenId);
    }

    function approve(address to, uint256 tokenId) external {
        address owner = ownerOf[tokenId];
        if (owner != msg.sender && !isApprovedForAll[owner][msg.sender]) revert NotAuthorised();
        getApproved[tokenId] = to;
        emit Approval(owner, to, tokenId);
    }

    function setApprovalForAll(address operator, bool approved) external {
        isApprovedForAll[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        if (ownerOf[tokenId] != from) revert NotOwner();
        if (msg.sender != from && getApproved[tokenId] != msg.sender && !isApprovedForAll[from][msg.sender]) {
            revert NotAuthorised();
        }
        delete getApproved[tokenId];
        ownerOf[tokenId] = to;
        unchecked {
            balanceOf[from] -= 1;
            balanceOf[to] += 1;
        }
        emit Transfer(from, to, tokenId);
    }
}

HintRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {Nonces} from "@openzeppelin/contracts/utils/Nonces.sol";
import {IERC20, IOptimisticOracleV3, IOptimisticOracleV3CallbackRecipient} from "./IOptimisticOracleV3.sol";

/// @title HintRegistry
/// @notice Permissionless, optimistic registry of *discovery hints* for EVM asset indexing.
///
/// The registry holds two kinds of public commitment:
///
///  1. **Asset hints** — anyone may register a `(chainId, token)` pair. Registration is
///     permissionless and unvalidated: it is a request that indexers scan that contract's
///     full log history at least once. Nothing here asserts the contract is legitimate.
///
///  2. **Index commitments** — an indexer publishes a merkle root over the
///     `account -> assets touched` table it derived for a block range, plus a second
///     root over the per-asset block ranges that table stands behind, plus a URI to
///     the full table. Both roots are *optimistic*: they finalize after a challenge
///     window unless someone bonds a challenge against them.
///
/// Money attaches to assets, not to chains. `requestIndexing` deposits funding on the
/// asset it names, and that funding is paid out per block of coverage: when an epoch
/// finalizes, its publisher claims `rewardPerBlock` for every block of an asset's
/// declared range that nobody has been paid for yet. A request therefore buys a
/// number of blocks of indexing for one contract, and a publisher is paid exactly
/// when it covers what someone paid to have covered. That is how the gas a publisher
/// fronts gets paid back: by the people who wanted the data, not by a sponsor the
/// contract has to trust.
///
/// Nothing here is a source of truth. The underlying logs are public on the source chain;
/// this contract only makes it cheap to discover *which* contracts are worth pulling
/// history for. A consumer that needs certainty re-derives the data from the chain.
///
/// # Dispute adjudication
///
/// Commitments are adjudicated in one of two modes, fixed at deployment:
///
///  - **Oracle mode** (`oracle != address(0)`): `publishIndex` asserts the commitment to
///    UMA's Optimistic Oracle V3 with a bond in `bondCurrency`. Anyone disputes it
///    through the oracle, and UMA's DVM — not this contract — decides. There is no
///    arbiter and no admin setter that can be reached: `arbiter()` is `address(0)` and
///    every `onlyLocalArbiter` entry point is permanently unreachable, whoever the
///    Ownable owner is. Economics and the gateway list are therefore fixed at
///    construction.
///
///  - **Local-arbiter mode** (`oracle == address(0)`): the pre-oracle fallback, for chains
///    with no oracle deployment. The contract's owner (OpenZeppelin `Ownable2Step`) is
///    the arbiter: it settles challenges and may edit the gateway list. This mode is a
///    concession to reality, not the design: a deployment in it is only as neutral as
///    that one key, which is why `evmscan-deploy` prints the mode it is deploying in.
///
/// In both modes the bonds, the challenge window and the coverage pricing are immutable:
/// they are stated once in the constructor and no key can change them afterwards. The
/// arbiter key itself can be rotated, in two steps — `transferOwnership` by the current
/// owner, `acceptOwnership` by the next — so a leaked key is replaced rather than the
/// whole registry, and a mistyped address cannot orphan it. Rotation changes who
/// settles disputes, never what the rules are.
contract HintRegistry is IOptimisticOracleV3CallbackRecipient, Ownable2Step, EIP712, Nonces {
    // --------------------------------------------------------------------
    // Types
    // --------------------------------------------------------------------

    /// @dev Sentinels, not EIP numbers: 721 and 1155 do not fit in a uint8.
    uint8 public constant KIND_UNKNOWN = 0;
    uint8 public constant KIND_ERC20 = 20;
    uint8 public constant KIND_ERC721 = 21;
    uint8 public constant KIND_ERC1155 = 55;

    enum EpochStatus {
        None,
        Proposed,
        Challenged,
        Finalized,
        Rejected
    }

    struct Asset {
        uint64 chainId;
        address token;
        uint8 kind;
        /// @dev Hint for where the indexer should start scanning (usually the deploy
        ///      block). The indexer may correct this downward; it is not trusted.
        uint64 fromBlock;
        address registrant;
        uint64 registeredAt;
        uint256 bond;
        bool active;
    }

    /// @notice What an asset has left to pay indexers, and which blocks have already
    ///         been paid for.
    struct Funding {
        /// @dev Wei available to pay coverage claims. Not refundable: it buys blocks.
        uint256 balance;
        /// @dev Contiguous block range already paid for. `paidTo == 0` means nothing
        ///      has been paid yet; block 0 is never a real coverage boundary.
        uint64 paidFrom;
        uint64 paidTo;
        /// @dev Every wei ever committed to this asset, which only ever goes up.
        ///
        ///      `balance` answers "can this asset still pay an indexer", and drains
        ///      as coverage is claimed — so an asset that has been indexed well and
        ///      paid for reads as zero, indistinguishable from one nobody ever
        ///      wanted. That makes it useless as a measure of demand, which is the
        ///      question worth asking of a list of contracts: who cared enough about
        ///      this one to pay for it?
        ///
        ///      Kept as its own counter rather than derived from the AssetFunded
        ///      events, because a caller ranking a few hundred assets should not have
        ///      to replay a log to do it, and a contract cannot read its own events.
        uint256 vouched;
    }

    struct Epoch {
        uint64 chainId;
        uint64 fromBlock;
        uint64 toBlock;
        /// @dev Merkle root over leaves `keccak256(abi.encode(account, chainId, assetsHash))`.
        bytes32 root;
        /// @dev Merkle root over leaves `keccak256(abi.encode(assetKey, fromBlock, toBlock))`,
        ///      one per asset the publisher scanned, declaring the range it stands behind.
        bytes32 coverageRoot;
        /// @dev Pointer to the full index table (ipfs://, https://, ...).
        string uri;
        address publisher;
        /// @dev Set when a dispute is opened through `challengeIndex`. A dispute raised
        ///      directly at the oracle leaves this zero; the oracle records the disputer.
        address challenger;
        uint256 bond;
        uint64 publishedAt;
        uint64 challengeDeadline;
        EpochStatus status;
        /// @dev Oracle mode only: the OOv3 assertion backing this commitment.
        bytes32 assertionId;
    }

    /// @notice One asset's entry in a finalized epoch's coverage tree, with its proof.
    struct CoverageClaim {
        bytes32 key;
        uint64 fromBlock;
        uint64 toBlock;
        bytes32[] proof;
    }

    /// @notice The prices a deployment is configured with, grouped so the constructor
    ///         states them in one place. Each is also readable individually.
    struct Economics {
        /// @dev Wei `registerAsset` requires; refundable via `revokeAsset`.
        uint256 assetBond;
        /// @dev Per-commitment bond: wei in local-arbiter mode, `bondCurrency` units in
        ///      oracle mode.
        uint256 publisherBond;
        /// @dev Seconds a commitment stays disputable; assertion liveness in oracle mode.
        uint256 challengeWindow;
        /// @dev Least `requestIndexing` accepts above the asset bond.
        uint256 minFunding;
        /// @dev Paid per newly covered block of a funded asset.
        uint256 rewardPerBlock;
    }

    // --------------------------------------------------------------------
    // Storage
    // --------------------------------------------------------------------

    /// @notice UMA Optimistic Oracle V3, or `address(0)` in local-arbiter mode.
    IOptimisticOracleV3 public immutable oracle;
    /// @notice ERC-20 the oracle bonds are denominated in. Zero in local-arbiter mode.
    IERC20 public immutable bondCurrency;

    uint256 public immutable assetBond;
    /// @notice Bond a publisher posts per commitment: wei in local-arbiter mode, units of
    ///         `bondCurrency` in oracle mode.
    uint256 public immutable publisherBond;
    /// @notice Challenge window in seconds. In oracle mode this is the assertion liveness.
    uint256 public immutable challengeWindow;
    /// @notice Minimum funding `requestIndexing` accepts on top of the asset bond.
    uint256 public immutable minFunding;
    /// @notice Paid to a publisher per newly covered block of a funded asset.
    uint256 public immutable rewardPerBlock;

    mapping(bytes32 => Asset) private _assets;
    mapping(bytes32 => Funding) private _funding;
    bytes32[] private _assetKeys;

    Epoch[] private _epochs;
    /// @notice chainId => id of the most recent finalized epoch, +1 (0 means none).
    mapping(uint64 => uint256) private _latestFinalized;
    /// @notice assertionId => epoch id, +1 (0 means unknown).
    mapping(bytes32 => uint256) private _assertionEpoch;

    /// @notice ERC-3668 gateway URL templates (`{sender}` and `{data}` placeholders)
    ///         that serve leaves and proofs for `contractsOf`. Any number of
    ///         operators may run one; a client may also bring its own.
    string[] private _gateways;

    /// @notice Who wants a contract indexed. A vote is a priority signal for
    ///         indexers and nothing else: it buys no position, needs no
    ///         registration and no bond, and an indexer may weigh it however it
    ///         likes. One address counts once per asset. Kept enumerable, like
    ///         assets, so an indexer reads it as state rather than replaying logs.
    struct Demand {
        uint64 chainId;
        address token;
        uint64 voters;
    }

    mapping(bytes32 => Demand) private _demand;
    mapping(bytes32 => mapping(address => bool)) private _voted;
    bytes32[] private _demandKeys;

    // --------------------------------------------------------------------
    // Events
    // --------------------------------------------------------------------

    event AssetRegistered(
        bytes32 indexed key,
        uint64 indexed chainId,
        address indexed token,
        uint8 kind,
        uint64 fromBlock,
        address registrant
    );
    event AssetRevoked(bytes32 indexed key, address indexed registrant);
    event IndexPublished(
        uint256 indexed epochId,
        uint64 indexed chainId,
        uint64 fromBlock,
        uint64 toBlock,
        bytes32 root,
        bytes32 coverageRoot,
        string uri,
        address publisher
    );
    /// @notice Oracle mode only: the commitment was asserted to the oracle.
    event IndexAsserted(uint256 indexed epochId, bytes32 indexed assertionId);
    event IndexChallenged(uint256 indexed epochId, address indexed challenger);
    event IndexResolved(uint256 indexed epochId, EpochStatus status);
    /// @notice Emitted once, at deployment. Everything in it is immutable, so this is the
    ///         whole configuration history of the contract.
    event RegistryConfigured(
        address indexed oracle,
        address indexed bondCurrency,
        address indexed arbiter,
        uint256 assetBond,
        uint256 publisherBond,
        uint256 challengeWindow,
        uint256 minFunding,
        uint256 rewardPerBlock
    );
    event AssetFunded(bytes32 indexed key, address indexed funder, uint256 amount, uint256 balance);
    event CoverageRewarded(
        uint256 indexed epochId,
        bytes32 indexed key,
        address indexed publisher,
        uint64 fromBlock,
        uint64 toBlock,
        uint64 newBlocks,
        uint256 reward
    );
    event GatewaysUpdated(string[] urls);
    event Voted(bytes32 indexed key, uint64 indexed chainId, address indexed token, address voter, uint64 voters);

    /// @dev EIP-712 type of a vote somebody else carries to the chain.
    bytes32 private constant VOTE_TYPEHASH =
        keccak256("Vote(address voter,uint64 chainId,address[] tokens,uint256 nonce,uint256 deadline)");
    error ExpiredSignature();
    error BadSigner();

    // --------------------------------------------------------------------
    // Errors
    // --------------------------------------------------------------------

    error NotArbiter();
    error NotOracle();
    error NotRegistrant();
    error AlreadyRegistered();
    error UnknownAsset();
    error UnknownEpoch();
    error UnknownAssertion();
    error BadBond();
    error BadFee();
    error BadConfig();
    error BadRange();
    error BadStatus();
    error BadProof();
    error WindowOpen();
    error WindowClosed();
    error TransferFailed();
    error CurrencyTransferFailed();
    /// @notice The entry point exists only in local-arbiter mode.
    error OracleModeOnly();
    /// @dev ERC-3668: the answer lives off-chain; fetch it from `urls`, then call back.
    error OffchainLookup(address sender, string[] urls, bytes callData, bytes4 callbackFunction, bytes extraData);
    error NoFinalizedEpoch();
    error StaleEpoch();
    error Unsorted();

    /// @dev Guards the entry points that only exist in local-arbiter mode. In oracle mode
    ///      the first check fails for everyone, owner included, so there is no admin
    ///      path at all; in local mode the owner is the arbiter.
    modifier onlyLocalArbiter() {
        if (address(oracle) != address(0)) revert OracleModeOnly();
        if (msg.sender != owner()) revert NotArbiter();
        _;
    }

    /// @notice Who settles challenges: the owner in local-arbiter mode, zero in oracle
    ///         mode, where nobody does. Kept as a view under the old getter's name so
    ///         clients that read the mode off it keep working.
    function arbiter() public view returns (address) {
        return address(oracle) == address(0) ? owner() : address(0);
    }

    modifier onlyOracle() {
        if (msg.sender != address(oracle) || address(oracle) == address(0)) revert NotOracle();
        _;
    }

    /// @param oracle_ UMA Optimistic Oracle V3, or `address(0)` to fall back to a local
    ///        arbiter on a chain with no oracle deployment.
    /// @param bondCurrency_ ERC-20 for oracle bonds. Must be zero in local-arbiter mode.
    /// @param arbiter_ Local arbiter, the initial owner. Must be zero in oracle mode,
    ///        where the deployer becomes an owner with nothing to own.
    /// @param econ_ Bonds, window and coverage pricing. See `Economics`.
    /// @param gateways_ Initial ERC-3668 gateway templates for `contractsOf`. In oracle
    ///        mode this list is final, because no setter is reachable.
    constructor(
        address oracle_,
        address bondCurrency_,
        address arbiter_,
        Economics memory econ_,
        string[] memory gateways_
    ) Ownable(arbiter_ == address(0) ? msg.sender : arbiter_) EIP712("HintRegistry", "1") {
        if (econ_.challengeWindow == 0 || econ_.challengeWindow > type(uint64).max) revert BadConfig();

        if (oracle_ != address(0)) {
            // Oracle mode: no arbiter may exist, or the "neutral" deployment still has a
            // key that can settle disputes.
            if (arbiter_ != address(0) || bondCurrency_ == address(0)) revert BadConfig();
            // A bond the oracle would reject makes every publish revert; catch it here
            // rather than after deployment.
            if (econ_.publisherBond < IOptimisticOracleV3(oracle_).getMinimumBond(bondCurrency_)) revert BadBond();
        } else {
            if (arbiter_ == address(0) || bondCurrency_ != address(0)) revert BadConfig();
        }

        oracle = IOptimisticOracleV3(oracle_);
        bondCurrency = IERC20(bondCurrency_);
        assetBond = econ_.assetBond;
        publisherBond = econ_.publisherBond;
        challengeWindow = econ_.challengeWindow;
        minFunding = econ_.minFunding;
        rewardPerBlock = econ_.rewardPerBlock;
        _setGateways(gateways_);

        emit RegistryConfigured(
            oracle_,
            bondCurrency_,
            arbiter_,
            econ_.assetBond,
            econ_.publisherBond,
            econ_.challengeWindow,
            econ_.minFunding,
            econ_.rewardPerBlock
        );
    }

    /// @notice True when disputes are settled by the optimistic oracle rather than a key.
    function oracleMode() public view returns (bool) {
        return address(oracle) != address(0);
    }

    // --------------------------------------------------------------------
    // Asset hints
    // --------------------------------------------------------------------

    /// @notice Deterministic key for an asset hint.
    function assetKey(uint64 chainId, address token) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(chainId, token));
    }

    /// @notice Register a `(chainId, token)` pair for indexing. Permissionless.
    /// @dev The bond exists to price spam, not to confer legitimacy. It is refundable
    ///      via `revokeAsset`. An asset registered this way has no funding, so nobody
    ///      is paid to index it; `requestIndexing` is the version that pays.
    function registerAsset(uint64 chainId, address token, uint8 kind, uint64 fromBlock)
        external
        payable
        returns (bytes32 key)
    {
        if (msg.value != assetBond) revert BadBond();
        key = assetKey(chainId, token);
        if (_assets[key].active) revert AlreadyRegistered();
        _register(key, chainId, token, kind, fromBlock, msg.value);
    }

    /// @notice Pay for a `(chainId, token)` pair to be indexed. Permissionless.
    /// @dev Registers the asset if it is not already, exactly as `registerAsset` does,
    ///      and deposits everything above the bond as that asset's funding. Funding is
    ///      paid out at `rewardPerBlock` per block of coverage a finalized epoch
    ///      declares for this asset, so a payment of `n * rewardPerBlock` buys `n`
    ///      blocks of indexing. For an asset that is already registered the whole
    ///      payment is funding.
    function requestIndexing(uint64 chainId, address token, uint8 kind, uint64 fromBlock)
        external
        payable
        returns (bytes32 key)
    {
        key = assetKey(chainId, token);
        uint256 funding = msg.value;
        if (!_assets[key].active) {
            if (msg.value < assetBond + minFunding) revert BadFee();
            funding = msg.value - assetBond;
            _register(key, chainId, token, kind, fromBlock, assetBond);
        } else if (msg.value < minFunding) {
            revert BadFee();
        }
        _fund(key, funding);
    }

    /// @notice Top up a registered asset's funding without touching its hint.
    /// @dev Where revenue from paid queries, or any other sponsor, lands.
    function fundAsset(bytes32 key) external payable {
        if (!_assets[key].active) revert UnknownAsset();
        _fund(key, msg.value);
    }

    function _fund(bytes32 key, uint256 amount) private {
        Funding storage f = _funding[key];
        f.balance += amount;
        // The only place either number rises, and `vouched` is the one that never
        // falls — claimCoverage spends `balance` and leaves this alone.
        f.vouched += amount;
        emit AssetFunded(key, msg.sender, amount, f.balance);
    }

    function _register(bytes32 key, uint64 chainId, address token, uint8 kind, uint64 fromBlock, uint256 bond)
        private
    {
        // A revoked asset keeps its row and its place in the key list, so a re-register
        // must not add a second entry: `listAssets` is how indexers bootstrap their scan
        // set, and a duplicate there is a scan counted twice.
        bool known = _assets[key].registeredAt != 0;

        _assets[key] = Asset({
            chainId: chainId,
            token: token,
            kind: kind,
            fromBlock: fromBlock,
            registrant: msg.sender,
            registeredAt: uint64(block.timestamp),
            bond: bond,
            active: true
        });
        if (!known) _assetKeys.push(key);

        emit AssetRegistered(key, chainId, token, kind, fromBlock, msg.sender);
    }

    /// @notice Withdraw an asset hint and reclaim its bond.
    /// @dev Indexers keep whatever they already derived; this only stops future scanning.
    ///      Funding is not returned: it bought blocks, and an indexer may already have
    ///      scanned them on the strength of it. Whatever is left stays claimable.
    function revokeAsset(bytes32 key) external {
        Asset storage a = _assets[key];
        if (!a.active) revert UnknownAsset();
        if (a.registrant != msg.sender) revert NotRegistrant();

        uint256 refund = a.bond;
        a.active = false;
        a.bond = 0;

        emit AssetRevoked(key, msg.sender);
        _pay(msg.sender, refund);
    }

    function getAsset(bytes32 key) external view returns (Asset memory) {
        return _assets[key];
    }

    function getFunding(bytes32 key) external view returns (Funding memory) {
        return _funding[key];
    }

    function isRegistered(uint64 chainId, address token) external view returns (bool) {
        return _assets[assetKey(chainId, token)].active;
    }

    function assetCount() external view returns (uint256) {
        return _assetKeys.length;
    }

    /// @notice Page through registered assets. Used by indexers to bootstrap their
    ///         scan set without replaying every `AssetRegistered` log.
    function listAssets(uint256 offset, uint256 limit) external view returns (Asset[] memory page) {
        uint256 n = _assetKeys.length;
        if (offset >= n) return new Asset[](0);
        uint256 end = offset + limit;
        if (end > n) end = n;
        page = new Asset[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            page[i - offset] = _assets[_assetKeys[i]];
        }
    }

    // --------------------------------------------------------------------
    // Demand
    // --------------------------------------------------------------------

    /// @notice Ask for these contracts on `chainId` to be indexed. Free apart from
    ///         gas; a repeat vote from the same address for the same asset is a
    ///         no-op. Anyone can vote for anything, which is why this is a priority
    ///         signal and never a verdict — a bad vote wastes an indexer's queue
    ///         slot, not a reader's trust.
    function vote(uint64 chainId, address[] calldata tokens) external {
        _vote(msg.sender, chainId, tokens);
    }

    /// @notice The same vote, signed by `voter` and carried by whoever pays the gas.
    ///         The signature is EIP-712 over `Vote(voter, chainId, tokens, nonce,
    ///         deadline)` with this contract as the verifying contract; the nonce is
    ///         `nonces(voter)` and is spent whether or not any token was new, so a
    ///         signature is good for exactly one transaction. Nothing about the
    ///         carrier matters: the vote is the voter's, counted once like any other.
    function voteFor(
        address voter,
        uint64 chainId,
        address[] calldata tokens,
        uint256 deadline,
        bytes calldata signature
    ) external {
        if (block.timestamp > deadline) revert ExpiredSignature();
        uint256 nonce = _useNonce(voter);
        bytes32 structHash = keccak256(
            abi.encode(VOTE_TYPEHASH, voter, chainId, keccak256(abi.encodePacked(tokens)), nonce, deadline)
        );
        if (ECDSA.recover(_hashTypedDataV4(structHash), signature) != voter) revert BadSigner();
        _vote(voter, chainId, tokens);
    }

    function _vote(address voter, uint64 chainId, address[] calldata tokens) private {
        for (uint256 i = 0; i < tokens.length; i++) {
            bytes32 key = assetKey(chainId, tokens[i]);
            if (_voted[key][voter]) continue;
            _voted[key][voter] = true;
            Demand storage d = _demand[key];
            if (d.voters == 0) {
                d.chainId = chainId;
                d.token = tokens[i];
                _demandKeys.push(key);
            }
            d.voters += 1;
            emit Voted(key, chainId, tokens[i], voter, d.voters);
        }
    }

    function demandOf(bytes32 key) external view returns (Demand memory) {
        return _demand[key];
    }

    function hasVoted(bytes32 key, address voter) external view returns (bool) {
        return _voted[key][voter];
    }

    function demandCount() external view returns (uint256) {
        return _demandKeys.length;
    }

    /// @notice Page through voted assets, in first-vote order.
    function listDemand(uint256 offset, uint256 limit) external view returns (Demand[] memory page) {
        uint256 n = _demandKeys.length;
        if (offset >= n) return new Demand[](0);
        uint256 end = offset + limit;
        if (end > n) end = n;
        page = new Demand[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            page[i - offset] = _demand[_demandKeys[i]];
        }
    }

    // --------------------------------------------------------------------
    // Optimistic index commitments
    // --------------------------------------------------------------------

    /// @notice Publish a merkle commitment over the derived `account -> assets` index
    ///         for `[fromBlock, toBlock]` on `chainId`, together with the per-asset
    ///         coverage it stands behind.
    /// @dev In oracle mode the bond is `publisherBond` units of `bondCurrency`, pulled
    ///      from the caller (approve this contract first) and forwarded to the oracle;
    ///      `msg.value` must be zero. In local-arbiter mode the bond is `msg.value`.
    function publishIndex(
        uint64 chainId,
        uint64 fromBlock,
        uint64 toBlock,
        bytes32 root,
        bytes32 coverageRoot,
        string calldata uri
    ) external payable returns (uint256 epochId) {
        if (toBlock < fromBlock) revert BadRange();
        bool viaOracle = oracleMode();
        if (msg.value != (viaOracle ? 0 : publisherBond)) revert BadBond();

        epochId = _epochs.length;
        Epoch storage e = _epochs.push();
        e.chainId = chainId;
        e.fromBlock = fromBlock;
        e.toBlock = toBlock;
        e.root = root;
        e.coverageRoot = coverageRoot;
        e.uri = uri;
        e.publisher = msg.sender;
        e.bond = viaOracle ? publisherBond : msg.value;
        e.publishedAt = uint64(block.timestamp);
        e.challengeDeadline = uint64(block.timestamp + challengeWindow);
        e.status = EpochStatus.Proposed;

        _announce(epochId);
        if (viaOracle) _assert(epochId);
    }

    /// @dev Split out of `publishIndex` to keep its stack shallow; reads the epoch back
    ///      from storage so the event states exactly what was stored.
    function _announce(uint256 epochId) private {
        Epoch storage e = _epochs[epochId];
        emit IndexPublished(epochId, e.chainId, e.fromBlock, e.toBlock, e.root, e.coverageRoot, e.uri, e.publisher);
    }

    /// @dev Oracle mode: back the stored epoch with an assertion and remember the mapping.
    function _assert(uint256 epochId) private {
        bytes32 assertionId = _assertToOracle(epochId);
        _epochs[epochId].assertionId = assertionId;
        _assertionEpoch[assertionId] = epochId + 1;
        emit IndexAsserted(epochId, assertionId);
    }

    /// @notice Dispute a proposed commitment before its window closes.
    /// @dev Oracle mode: a thin wrapper over `disputeAssertion`. The disputer's bond is
    ///      `publisherBond` units of `bondCurrency`, pulled from the caller (approve this
    ///      contract first), and UMA's DVM decides the outcome. Disputing at the oracle
    ///      directly works too and is equivalent; this path only exists so that consumers
    ///      have one address to talk to.
    ///      Local-arbiter mode: the challenge is bonded in wei and settled by `arbiter`.
    function challengeIndex(uint256 epochId) external payable {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        Epoch storage e = _epochs[epochId];
        if (e.status != EpochStatus.Proposed) revert BadStatus();
        if (block.timestamp > e.challengeDeadline) revert WindowClosed();

        if (oracleMode()) {
            if (msg.value != 0) revert BadBond();
            // Recorded before the call: the oracle's dispute callback re-enters here and
            // emits the event with this address.
            e.challenger = msg.sender;
            uint256 bond = e.bond;
            _currencyCall(abi.encodeCall(IERC20.transferFrom, (msg.sender, address(this), bond)));
            _currencyCall(abi.encodeCall(IERC20.approve, (address(oracle), bond)));
            oracle.disputeAssertion(e.assertionId, msg.sender);
            // Belt and braces: a well-behaved oracle already flipped the status through
            // `assertionDisputedCallback`.
            if (e.status == EpochStatus.Proposed) {
                e.status = EpochStatus.Challenged;
                emit IndexChallenged(epochId, msg.sender);
            }
            return;
        }

        if (msg.value != e.bond) revert BadBond();
        e.status = EpochStatus.Challenged;
        e.challenger = msg.sender;
        e.bond += msg.value;

        emit IndexChallenged(epochId, msg.sender);
    }

    /// @notice Local-arbiter mode only: resolve a challenged commitment. `upheld == true`
    ///         means the published root was correct and the challenger forfeits.
    /// @dev Unreachable in oracle mode, where UMA's vote decides instead.
    function resolveChallenge(uint256 epochId, bool upheld) external onlyLocalArbiter {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        if (_epochs[epochId].status != EpochStatus.Challenged) revert BadStatus();
        _resolve(epochId, upheld);
    }

    /// @notice Finalize a commitment once its window has closed.
    /// @dev Oracle mode: settles the assertion at the oracle, which resolves the epoch
    ///      through the callback. Reverts while the assertion is still live or, once
    ///      disputed, until UMA has voted. Local-arbiter mode: finalizes an unchallenged
    ///      commitment after its deadline.
    ///
    ///      Finalizing returns the publisher's bond; the reward for the coverage the
    ///      epoch declared is claimed separately, per asset, with `claimCoverage`.
    function finalizeIndex(uint256 epochId) external {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        Epoch storage e = _epochs[epochId];

        if (oracleMode()) {
            if (e.status != EpochStatus.Proposed && e.status != EpochStatus.Challenged) revert BadStatus();
            bool upheld = oracle.settleAndGetAssertionResult(e.assertionId);
            // The callback normally did this already; settle's own return value is the
            // same answer, so apply it if the callback was skipped.
            if (e.status == EpochStatus.Proposed || e.status == EpochStatus.Challenged) {
                _resolve(epochId, upheld);
            }
            return;
        }

        if (e.status != EpochStatus.Proposed) revert BadStatus();
        if (block.timestamp <= e.challengeDeadline) revert WindowOpen();
        _resolve(epochId, true);
    }

    // --------------------------------------------------------------------
    // Coverage rewards
    // --------------------------------------------------------------------

    /// @notice Pay a finalized epoch's publisher for the coverage it declared.
    /// @dev Anyone may call this; the money always goes to the epoch's publisher. Each
    ///      claim proves one `(asset, fromBlock, toBlock)` leaf against the epoch's
    ///      coverage root and is paid `rewardPerBlock` for every block in that range
    ///      that no earlier claim on the asset has been paid for, capped by the
    ///      asset's funding. Replaying a claim, or claiming a range another epoch
    ///      already covered, pays nothing, so the number of epochs posted does not
    ///      change what a block of coverage is worth.
    ///
    ///      Gaps are paid as if covered: a claim of [100, 200] after [10, 20] was paid
    ///      pays for 21..200. The claim is a statement the publisher bonded and nobody
    ///      challenged, which is the same standing every other leaf in the epoch has.
    ///
    ///      A claim that pays nothing leaves the paid range alone, so covering an
    ///      unfunded asset is not forfeited: whoever funds it later pays for those
    ///      blocks. A claim the balance only partly covers marks the whole range paid;
    ///      funding is a cap, and the shortfall is the publisher's to accept or not.
    /// @return total Wei paid to the publisher across all claims.
    function claimCoverage(uint256 epochId, CoverageClaim[] calldata claims) external returns (uint256 total) {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        Epoch storage e = _epochs[epochId];
        if (e.status != EpochStatus.Finalized) revert BadStatus();

        for (uint256 i = 0; i < claims.length; i++) {
            CoverageClaim calldata c = claims[i];
            if (c.fromBlock < e.fromBlock || c.toBlock > e.toBlock || c.toBlock < c.fromBlock || c.toBlock == 0) {
                revert BadRange();
            }
            if (_assets[c.key].chainId != e.chainId) revert UnknownAsset();
            if (!_verify(e.coverageRoot, coverageLeaf(c.key, c.fromBlock, c.toBlock), c.proof)) revert BadProof();

            Funding storage f = _funding[c.key];
            uint64 fresh = _fresh(f, c.fromBlock, c.toBlock);
            uint256 reward = uint256(fresh) * rewardPerBlock;
            if (reward > f.balance) reward = f.balance;
            if (reward > 0) {
                _extend(f, c.fromBlock, c.toBlock);
                f.balance -= reward;
                total += reward;
            }

            emit CoverageRewarded(epochId, c.key, e.publisher, c.fromBlock, c.toBlock, fresh, reward);
        }

        _pay(e.publisher, total);
    }

    /// @notice What `claimCoverage` would pay today for one asset range, before any
    ///         other claim moves the paid range. Lets a publisher decide whether an
    ///         epoch is worth the gas before posting it.
    function claimable(bytes32 key, uint64 fromBlock, uint64 toBlock) external view returns (uint256) {
        if (toBlock < fromBlock || toBlock == 0) return 0;
        Funding storage f = _funding[key];
        uint256 reward = uint256(_fresh(f, fromBlock, toBlock)) * rewardPerBlock;
        return reward > f.balance ? f.balance : reward;
    }

    /// @dev How many blocks of [fromBlock, toBlock] lie outside the paid range.
    function _fresh(Funding storage f, uint64 fromBlock, uint64 toBlock) private view returns (uint64 fresh) {
        if (f.paidTo == 0) return toBlock - fromBlock + 1;
        if (fromBlock < f.paidFrom) fresh += f.paidFrom - fromBlock;
        if (toBlock > f.paidTo) fresh += toBlock - f.paidTo;
    }

    /// @dev Grows the paid range to include [fromBlock, toBlock].
    function _extend(Funding storage f, uint64 fromBlock, uint64 toBlock) private {
        if (f.paidTo == 0) {
            f.paidFrom = fromBlock;
            f.paidTo = toBlock;
            return;
        }
        if (fromBlock < f.paidFrom) f.paidFrom = fromBlock;
        if (toBlock > f.paidTo) f.paidTo = toBlock;
    }

    // --------------------------------------------------------------------
    // Oracle callbacks
    // --------------------------------------------------------------------

    /// @inheritdoc IOptimisticOracleV3CallbackRecipient
    /// @dev Called by the oracle when an assertion expires undisputed or the DVM votes.
    function assertionResolvedCallback(bytes32 assertionId, bool assertedTruthfully) external onlyOracle {
        uint256 epochId = _epochForAssertion(assertionId);
        EpochStatus s = _epochs[epochId].status;
        // Already settled, e.g. through `finalizeIndex`'s fallback. Not an error.
        if (s != EpochStatus.Proposed && s != EpochStatus.Challenged) return;
        _resolve(epochId, assertedTruthfully);
    }

    /// @inheritdoc IOptimisticOracleV3CallbackRecipient
    /// @dev Called by the oracle when anyone disputes, including disputes raised at the
    ///      oracle rather than through `challengeIndex`.
    function assertionDisputedCallback(bytes32 assertionId) external onlyOracle {
        uint256 epochId = _epochForAssertion(assertionId);
        Epoch storage e = _epochs[epochId];
        if (e.status != EpochStatus.Proposed) return;
        e.status = EpochStatus.Challenged;
        emit IndexChallenged(epochId, e.challenger);
    }

    // --------------------------------------------------------------------
    // Views
    // --------------------------------------------------------------------

    function epochCount() external view returns (uint256) {
        return _epochs.length;
    }

    function getEpoch(uint256 epochId) external view returns (Epoch memory) {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        return _epochs[epochId];
    }

    /// @notice The oracle assertion backing a commitment. Zero in local-arbiter mode.
    function assertionOf(uint256 epochId) external view returns (bytes32) {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        return _epochs[epochId].assertionId;
    }

    /// @notice Reverse lookup from an oracle assertion to its commitment.
    function epochOfAssertion(bytes32 assertionId) external view returns (bool found, uint256 epochId) {
        uint256 slot = _assertionEpoch[assertionId];
        if (slot == 0) return (false, 0);
        return (true, slot - 1);
    }

    /// @notice Most recent finalized epoch for a chain.
    /// @return found False when the chain has no finalized epoch yet.
    function latestFinalizedEpoch(uint64 chainId) external view returns (bool found, uint256 epochId, Epoch memory e) {
        uint256 slot = _latestFinalized[chainId];
        if (slot == 0) return (false, 0, e);
        epochId = slot - 1;
        return (true, epochId, _epochs[epochId]);
    }

    // --------------------------------------------------------------------
    // Merkle verification
    // --------------------------------------------------------------------

    /// @notice Leaf encoding for the index commitment.
    /// @param assetsDigest keccak256 over the ascending-sorted, packed asset addresses the
    ///        account touched on `chainId` within the epoch range.
    function leafHash(address account, uint64 chainId, bytes32 assetsDigest) public pure returns (bytes32) {
        return keccak256(abi.encode(account, chainId, assetsDigest));
    }

    /// @notice Leaf encoding for the coverage commitment.
    function coverageLeaf(bytes32 key, uint64 fromBlock, uint64 toBlock) public pure returns (bytes32) {
        return keccak256(abi.encode(key, fromBlock, toBlock));
    }

    /// @notice Verify an account's membership in a finalized (or proposed) commitment.
    /// @dev Sorted-pair merkle tree, matching the indexer's builder.
    function verifyInclusion(uint256 epochId, address account, bytes32 assetsDigest, bytes32[] calldata proof)
        external
        view
        returns (bool)
    {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        Epoch storage e = _epochs[epochId];
        return _verify(e.root, leafHash(account, e.chainId, assetsDigest), proof);
    }

    /// @notice Verify an asset range's membership in an epoch's coverage commitment.
    function verifyCoverage(uint256 epochId, bytes32 key, uint64 fromBlock, uint64 toBlock, bytes32[] calldata proof)
        external
        view
        returns (bool)
    {
        if (epochId >= _epochs.length) revert UnknownEpoch();
        return _verify(_epochs[epochId].coverageRoot, coverageLeaf(key, fromBlock, toBlock), proof);
    }

    function _verify(bytes32 root, bytes32 node, bytes32[] memory proof) private pure returns (bool) {
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 p = proof[i];
            node = node <= p ? keccak256(abi.encodePacked(node, p)) : keccak256(abi.encodePacked(p, node));
        }
        return node == root;
    }

    // --------------------------------------------------------------------
    // Verified lookups (ERC-3668, CCIP Read)
    // --------------------------------------------------------------------

    /// @notice Which contracts `account` has touched on `chainId`, per the latest
    ///         finalized commitment.
    /// @dev Always reverts with `OffchainLookup`. An ERC-3668 client fetches the
    ///      account's leaf and proof from any listed gateway and calls
    ///      `contractsOfCallback`, which checks them against the root stored here. A
    ///      gateway can therefore withhold an answer but cannot forge one, and the
    ///      callback refuses anything but the latest finalized epoch so it cannot
    ///      serve a stale one either.
    function contractsOf(uint64 chainId, address account) external view returns (address[] memory) {
        if (_latestFinalized[chainId] == 0) revert NoFinalizedEpoch();
        revert OffchainLookup(
            address(this),
            _gateways,
            abi.encodeWithSelector(this.contractsOf.selector, chainId, account),
            this.contractsOfCallback.selector,
            abi.encode(chainId, account)
        );
    }

    /// @notice ERC-3668 callback for `contractsOf`.
    /// @param response abi.encode(uint256 epochId, address[] assets, bytes32[] proof)
    /// @param extraData abi.encode(uint64 chainId, address account), as issued above
    function contractsOfCallback(bytes calldata response, bytes calldata extraData)
        external
        view
        returns (address[] memory assets)
    {
        (uint64 chainId, address account) = abi.decode(extraData, (uint64, address));
        uint256 epochId;
        bytes32[] memory proof;
        (epochId, assets, proof) = abi.decode(response, (uint256, address[], bytes32[]));

        uint256 slot = _latestFinalized[chainId];
        if (slot == 0) revert NoFinalizedEpoch();
        if (epochId != slot - 1) revert StaleEpoch();

        Epoch storage e = _epochs[epochId];
        if (!_verify(e.root, leafHash(account, chainId, assetsHash(assets)), proof)) revert BadProof();
    }

    /// @notice Digest of an account's asset list: keccak256 over the addresses packed
    ///         to 20 bytes each, which must be strictly ascending (sorted, unique).
    function assetsHash(address[] memory assets) public pure returns (bytes32) {
        bytes memory packed;
        for (uint256 i = 0; i < assets.length; i++) {
            if (i > 0 && assets[i] <= assets[i - 1]) revert Unsorted();
            packed = abi.encodePacked(packed, assets[i]);
        }
        return keccak256(packed);
    }

    function gateways() external view returns (string[] memory) {
        return _gateways;
    }

    // --------------------------------------------------------------------
    // Local-arbiter admin
    //
    // Bonds, window and pricing are immutable, so this and resolveChallenge are the only
    // entry points a key holds, and both revert permanently in oracle mode. The key
    // itself rotates through Ownable2Step (transferOwnership, then acceptOwnership from
    // the new key). Gateways are discovery hints: whatever they return is verified by
    // `contractsOfCallback`, and an ERC-3668 client may ignore the list and bring its
    // own, so the worst a bad list can do is make a lookup fail.
    // --------------------------------------------------------------------

    /// @notice Replace the gateway list `contractsOf` advertises.
    function setGateways(string[] memory urls) external onlyLocalArbiter {
        _setGateways(urls);
    }

    function _setGateways(string[] memory urls) private {
        delete _gateways;
        for (uint256 i = 0; i < urls.length; i++) {
            _gateways.push(urls[i]);
        }
        emit GatewaysUpdated(urls);
    }

    // --------------------------------------------------------------------
    // Internals
    // --------------------------------------------------------------------

    /// @dev Applies an outcome to a commitment. Bonds are only moved in local-arbiter
    ///      mode; in oracle mode the oracle custodies them and pays the winner directly.
    function _resolve(uint256 epochId, bool upheld) private {
        Epoch storage e = _epochs[epochId];
        uint256 pot = e.bond;
        e.bond = 0;

        address recipient;
        if (upheld) {
            e.status = EpochStatus.Finalized;
            // Only move the pointer forward: with an oracle, an older epoch can resolve
            // after a newer one, and consumers read this as "latest".
            if (epochId + 1 > _latestFinalized[e.chainId]) _latestFinalized[e.chainId] = epochId + 1;
            recipient = e.publisher;
        } else {
            e.status = EpochStatus.Rejected;
            recipient = e.challenger;
        }

        emit IndexResolved(epochId, e.status);
        if (!oracleMode()) _pay(recipient, pot);
    }

    /// @dev Asserts the commitment to the oracle, bonding `publisherBond` of
    ///      `bondCurrency` pulled from the publisher.
    function _assertToOracle(uint256 epochId) private returns (bytes32) {
        uint256 bond = publisherBond;
        _currencyCall(abi.encodeCall(IERC20.transferFrom, (msg.sender, address(this), bond)));
        _currencyCall(abi.encodeCall(IERC20.approve, (address(oracle), bond)));

        return oracle.assertTruth(
            _claim(epochId),
            msg.sender, // asserter: the publisher gets the bond back, not this contract
            address(this), // callbackRecipient
            address(0), // escalationManager: none, so anyone may dispute
            uint64(challengeWindow),
            bondCurrency,
            bond,
            oracle.defaultIdentifier(),
            bytes32(0) // domainId
        );
    }

    /// @dev The assertion text UMA voters read if the commitment is disputed. It has to
    ///      state the claim in full, because a voter has only this string and the public
    ///      chain data to work from. Both roots are stated: the index root is what
    ///      consumers verify against, the coverage root is what the publisher gets paid
    ///      for, and a lie in either is grounds to reject.
    function _claim(uint256 epochId) private view returns (bytes memory) {
        Epoch storage e = _epochs[epochId];
        string memory uri = e.uri;
        return abi.encodePacked(
            "evm-scan index commitment asserted by ",
            _toHex(abi.encodePacked(e.publisher)),
            " at registry ",
            _toHex(abi.encodePacked(address(this))),
            ": epoch=",
            _toDecimal(epochId),
            " chainId=",
            _toDecimal(e.chainId),
            " fromBlock=",
            _toDecimal(e.fromBlock),
            " toBlock=",
            _toDecimal(e.toBlock),
            " root=",
            _toHex(abi.encodePacked(e.root)),
            " coverageRoot=",
            _toHex(abi.encodePacked(e.coverageRoot)),
            " uri=",
            uri,
            ". True if and only if root is the merkle root of the account-to-assets table"
            " derived from the source chain's logs over the inclusive block range, using the"
            " leaf encoding keccak256(abi.encode(account, chainId, assetsHash)) and a"
            " sorted-pair tree; coverageRoot is the merkle root, with the same tree rule, of"
            " leaves keccak256(abi.encode(assetKey, fromBlock, toBlock)) naming only asset"
            " ranges whose logs that table includes in full; and the full table is"
            " retrievable at uri."
        );
    }

    /// @dev Calls `bondCurrency` and treats an empty return as success, so tokens that
    ///      predate the bool-returning ERC-20 signature still work.
    function _currencyCall(bytes memory data) private {
        (bool ok, bytes memory ret) = address(bondCurrency).call(data);
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert CurrencyTransferFailed();
    }

    function _epochForAssertion(bytes32 assertionId) private view returns (uint256) {
        uint256 slot = _assertionEpoch[assertionId];
        if (slot == 0) revert UnknownAssertion();
        return slot - 1;
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    function _toDecimal(uint256 v) private pure returns (bytes memory) {
        if (v == 0) return "0";
        uint256 len;
        for (uint256 t = v; t != 0; t /= 10) len++;
        bytes memory out = new bytes(len);
        for (uint256 i = len; v != 0; v /= 10) {
            out[--i] = bytes1(uint8(48 + (v % 10)));
        }
        return out;
    }

    function _toHex(bytes memory raw) private pure returns (bytes memory) {
        bytes memory digits = "0123456789abcdef";
        bytes memory out = new bytes(2 + raw.length * 2);
        out[0] = "0";
        out[1] = "x";
        for (uint256 i = 0; i < raw.length; i++) {
            out[2 + i * 2] = digits[uint8(raw[i]) >> 4];
            out[3 + i * 2] = digits[uint8(raw[i]) & 0x0f];
        }
        return out;
    }
}

HintResolver.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {HintRegistry} from "./HintRegistry.sol";
import {DNSNameLib} from "./DNSNameLib.sol";

/// @title HintResolver
/// @notice An ENS resolver (ENSIP-10 wildcard, ERC-3668 CCIP-Read) that serves the
///         committed `account -> contracts` index as ENS records.
///
/// Bind it as the resolver of a label such as `hints.<yourname>.eth` in an ENSv2
/// registry and every account gets a name without anyone registering one:
///
///     <hex-address>.hints.<yourname>.eth
///     <hex-address>.<chainId>.hints.<yourname>.eth      (second label overrides the default chain)
///
/// The Universal Resolver finds this contract for any such name (it is the deepest
/// resolver on the path), sees it supports IExtendedResolver, and calls
/// `resolve(name, data)`. The account is parsed from the first label; the `node`
/// inside `data` is ignored, as ENSIP-10 allows, because identity comes from the name.
///
/// Records:
///
///   addr(node)                     the account itself
///   addr(node, 60)                 the account, as 20 bytes
///   text(node, "evmscan.contracts") the contracts the account touched, verified. Reverts
///                                  OffchainLookup at the registry's gateways; the callback
///                                  hands the answer to HintRegistry.contractsOfCallback,
///                                  which verifies it against the latest finalized root.
///   text(node, "evmscan.epoch")    id of that epoch
///   text(node, "evmscan.range")    "<fromBlock>-<toBlock>" the epoch covers
///   text(node, "evmscan.root")     the epoch's index root
///   text(node, "evmscan.uri")      the pointer that epoch committed: the index table, and
///                                  the digest of the membership filter beside it
///   text(node, "evmscan.registry") this resolver's HintRegistry
///   text(node, "evmscan.chain")    the chain the account was indexed on
///
/// Nothing here is configured by hand: gateways, epochs and roots are read from the
/// registry at call time. A gateway can withhold an answer but cannot forge one, and
/// cannot serve a stale epoch, exactly as with `HintRegistry.contractsOf`.
contract HintResolver {
    using DNSNameLib for bytes;

    HintRegistry public immutable registry;
    uint64 public immutable defaultChainId;

    // ERC-165 / ENSIP-10 / resolver profile selectors.
    bytes4 private constant IFACE_ERC165 = 0x01ffc9a7;
    bytes4 private constant IFACE_EXTENDED_RESOLVER = 0x9061b923; // resolve(bytes,bytes)
    bytes4 private constant SEL_ADDR = 0x3b3b57de; // addr(bytes32)
    bytes4 private constant SEL_ADDR_COIN = 0xf1cb7e06; // addr(bytes32,uint256)
    bytes4 private constant SEL_TEXT = 0x59d1d43c; // text(bytes32,string)
    uint256 private constant COIN_TYPE_ETH = 60;

    bytes32 private constant KEY_CONTRACTS = keccak256("evmscan.contracts");
    bytes32 private constant KEY_EPOCH = keccak256("evmscan.epoch");
    bytes32 private constant KEY_RANGE = keccak256("evmscan.range");
    bytes32 private constant KEY_ROOT = keccak256("evmscan.root");
    bytes32 private constant KEY_URI = keccak256("evmscan.uri");
    bytes32 private constant KEY_REGISTRY = keccak256("evmscan.registry");
    bytes32 private constant KEY_CHAIN = keccak256("evmscan.chain");

    /// @dev ERC-3668.
    error OffchainLookup(address sender, string[] urls, bytes callData, bytes4 callbackFunction, bytes extraData);
    /// @dev The profile `data` asks for is not one this resolver serves. Same shape the
    ///      Universal Resolver reports for an unknown profile.
    error UnsupportedResolverProfile(bytes4 selector);
    /// @dev The first label is not a hex account address.
    error InvalidAccountLabel();
    /// @dev The registry holds no finalized commitment for this chain yet.
    error NoFinalizedEpoch(uint64 chainId);

    constructor(HintRegistry registry_, uint64 defaultChainId_) {
        registry = registry_;
        defaultChainId = defaultChainId_;
    }

    // --------------------------------------------------------------------
    // ERC-165
    // --------------------------------------------------------------------

    function supportsInterface(bytes4 id) external pure returns (bool) {
        return id == IFACE_ERC165 || id == IFACE_EXTENDED_RESOLVER;
    }

    // --------------------------------------------------------------------
    // ENSIP-10
    // --------------------------------------------------------------------

    /// @notice Resolve a profile for a DNS-encoded name under this resolver.
    /// @dev Reverts `OffchainLookup` only for `text(node, "evmscan.contracts")`; every
    ///      other record is answered from chain state in this call.
    function resolve(bytes calldata name, bytes calldata data) external view returns (bytes memory) {
        (address account, uint64 chainId, bool ok) = parseName(name);
        if (!ok) revert InvalidAccountLabel();
        if (data.length < 4) revert UnsupportedResolverProfile(bytes4(0));
        bytes4 selector = bytes4(data[:4]);

        if (selector == SEL_ADDR) {
            return abi.encode(account);
        }
        if (selector == SEL_ADDR_COIN) {
            (, uint256 coinType) = abi.decode(data[4:], (bytes32, uint256));
            if (coinType == COIN_TYPE_ETH) return abi.encode(abi.encodePacked(account));
            return abi.encode(bytes(""));
        }
        if (selector == SEL_TEXT) {
            (, string memory key) = abi.decode(data[4:], (bytes32, string));
            return abi.encode(_text(account, chainId, key));
        }
        revert UnsupportedResolverProfile(selector);
    }

    /// @notice ERC-3668 callback for `text(node, "evmscan.contracts")`.
    /// @param response abi.encode(uint256 epochId, address[] assets, bytes32[] proof), as
    ///        the registry's gateway already produces for `contractsOf`.
    /// @param extraData abi.encode(uint64 chainId, address account), the shape the
    ///        registry's own callback expects, so verification is delegated wholesale:
    ///        StaleEpoch, BadProof and Unsorted bubble up unchanged.
    function resolveCallback(bytes calldata response, bytes calldata extraData) external view returns (bytes memory) {
        address[] memory assets = registry.contractsOfCallback(response, extraData);
        return abi.encode(contractsText(assets));
    }

    // --------------------------------------------------------------------
    // Name parsing and record formats, public so tests can table them
    // --------------------------------------------------------------------

    /// @notice Reads the account from the first label and the chain from the second
    ///         when it is decimal, else `defaultChainId`.
    function parseName(bytes calldata name) public view returns (address account, uint64 chainId, bool ok) {
        bytes memory n = name;
        (bytes memory first, uint256 next) = n.readLabel(0);
        (account, ok) = first.parseHexAddress();
        if (!ok) return (address(0), 0, false);
        chainId = defaultChainId;
        (bytes memory second,) = n.readLabel(next);
        (uint64 explicitChain, bool isChain) = second.parseDecimal();
        if (isChain) chainId = explicitChain;
        return (account, chainId, true);
    }

    /// @notice The `evmscan.contracts` record format: lowercase hex addresses joined by commas.
    function contractsText(address[] memory assets) public pure returns (string memory) {
        bytes memory out;
        for (uint256 i = 0; i < assets.length; i++) {
            if (i > 0) out = abi.encodePacked(out, ",");
            out = abi.encodePacked(out, DNSNameLib.toHexString(assets[i]));
        }
        return string(out);
    }

    // --------------------------------------------------------------------
    // Internals
    // --------------------------------------------------------------------

    function _text(address account, uint64 chainId, string memory key) private view returns (string memory) {
        bytes32 k = keccak256(bytes(key));
        if (k == KEY_REGISTRY) return DNSNameLib.toHexString(address(registry));
        if (k == KEY_CHAIN) return DNSNameLib.toDecimalString(chainId);

        if (k == KEY_CONTRACTS) {
            (bool found,,) = registry.latestFinalizedEpoch(chainId);
            if (!found) revert NoFinalizedEpoch(chainId);
            revert OffchainLookup(
                address(this),
                registry.gateways(),
                abi.encodeWithSelector(HintRegistry.contractsOf.selector, chainId, account),
                this.resolveCallback.selector,
                abi.encode(chainId, account)
            );
        }
        if (k == KEY_EPOCH || k == KEY_RANGE || k == KEY_ROOT || k == KEY_URI) {
            (bool found, uint256 epochId, HintRegistry.Epoch memory e) = registry.latestFinalizedEpoch(chainId);
            if (!found) return "";
            if (k == KEY_EPOCH) return DNSNameLib.toDecimalString(epochId);
            if (k == KEY_ROOT) return DNSNameLib.toHexString(e.root);
            // Returned verbatim. The publisher named this URI inside the same bonded
            // transaction as the root, and what hangs off it — the index table, and
            // the membership filter's digest in the manifest beside it — is the
            // caller's to fetch and parse. A resolver that parsed URIs would be
            // committing this contract to a document format it cannot verify.
            if (k == KEY_URI) return e.uri;
            return string(
                abi.encodePacked(
                    DNSNameLib.toDecimalString(e.fromBlock), "-", DNSNameLib.toDecimalString(e.toBlock)
                )
            );
        }
        return "";
    }
}

IOptimisticOracleV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice The subset of ERC-20 the registry needs to move assertion bonds.
interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

/// @notice The subset of UMA's Optimistic Oracle V3 the registry calls.
///
/// Only the methods used by the "data asserter" pattern are declared: assert a claim
/// with a bond, let anyone dispute it, and settle once liveness has passed. The full
/// interface lives in UMA's protocol repo; narrowing it here keeps the registry
/// dependency-free and makes the trust surface obvious.
///
/// Reference: https://docs.uma.xyz/developers/optimistic-oracle-v3/data-asserter
interface IOptimisticOracleV3 {
    /// @notice Price identifier used for plain data assertions ("ASSERT_TRUTH").
    function defaultIdentifier() external view returns (bytes32);

    /// @notice Smallest bond the oracle accepts for `currency`. A bond below this is
    ///         rejected, because a dispute has to be worth more than its gas.
    function getMinimumBond(address currency) external view returns (uint256);

    /// @notice Assert that `claim` is true, bonding `bond` of `currency`.
    /// @dev The bond is pulled from `msg.sender`; `asserter` is who gets it back on a
    ///      successful settlement. `callbackRecipient` receives the dispute and
    ///      resolution callbacks.
    /// @return assertionId Identifier to dispute or settle this assertion.
    function assertTruth(
        bytes calldata claim,
        address asserter,
        address callbackRecipient,
        address escalationManager,
        uint64 liveness,
        IERC20 currency,
        uint256 bond,
        bytes32 identifier,
        bytes32 domainId
    ) external returns (bytes32 assertionId);

    /// @notice Dispute an assertion before its liveness expires. Matches the asserter's
    ///         bond, pulled from `msg.sender`, and escalates to UMA's DVM vote.
    function disputeAssertion(bytes32 assertionId, address disputer) external;

    /// @notice Settle an expired or resolved assertion and return its outcome. Reverts
    ///         while the assertion is still live and undisputed.
    function settleAndGetAssertionResult(bytes32 assertionId) external returns (bool);

    /// @notice Outcome of an already-settled assertion. Reverts if it is not settled.
    function getAssertionResult(bytes32 assertionId) external view returns (bool);
}

/// @notice Callbacks the oracle invokes on an assertion's `callbackRecipient`.
/// @dev Implemented by HintRegistry. Both are called by the oracle only.
interface IOptimisticOracleV3CallbackRecipient {
    function assertionResolvedCallback(bytes32 assertionId, bool assertedTruthfully) external;
    function assertionDisputedCallback(bytes32 assertionId) external;
}

MockOptimisticOracleV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20, IOptimisticOracleV3, IOptimisticOracleV3CallbackRecipient} from "./IOptimisticOracleV3.sol";

/// @title MockOptimisticOracleV3
/// @notice A dev-chain stand-in for UMA's Optimistic Oracle V3.
///
/// Local chains have no UMA deployment, so this exists purely so the registry's oracle
/// mode can be run end to end before it meets a real oracle: it keeps the same external
/// interface, the same bond mechanics and the same callback order, and replaces the DVM
/// vote with a single `voter` key that calls `resolveDispute`.
///
/// It is not a security model. Never deploy it anywhere that matters — in oracle mode a
/// registry is exactly as neutral as the oracle behind it, and this one is a single key.
contract MockOptimisticOracleV3 is IOptimisticOracleV3 {
    struct Assertion {
        bytes claim;
        address asserter;
        address callbackRecipient;
        address disputer;
        IERC20 currency;
        uint256 bond;
        uint64 expiresAt;
        bool settled;
        bool resolvedTruthful;
        bool voteCast;
        bool voteTruthful;
    }

    /// @notice Stands in for the DVM: resolves disputed assertions.
    address public immutable voter;
    uint256 public immutable minimumBond;

    mapping(bytes32 => Assertion) private _assertions;
    uint256 private _nonce;

    event AssertionMade(bytes32 indexed assertionId, address indexed asserter, uint64 expiresAt);
    event AssertionDisputed(bytes32 indexed assertionId, address indexed disputer);
    event AssertionResolved(bytes32 indexed assertionId, bool truthful);

    error NotVoter();
    error UnknownAssertion();
    error AlreadyDisputed();
    error AlreadySettled();
    error StillLive();
    error DisputeWindowClosed();
    error AwaitingVote();
    error BondTooSmall();
    error TransferFailed();

    constructor(address voter_, uint256 minimumBond_) {
        voter = voter_;
        minimumBond = minimumBond_;
    }

    function defaultIdentifier() external pure returns (bytes32) {
        return "ASSERT_TRUTH";
    }

    function getMinimumBond(address) external view returns (uint256) {
        return minimumBond;
    }

    function assertTruth(
        bytes calldata claim,
        address asserter,
        address callbackRecipient,
        address, /* escalationManager */
        uint64 liveness,
        IERC20 currency,
        uint256 bond,
        bytes32, /* identifier */
        bytes32 /* domainId */
    ) external returns (bytes32 assertionId) {
        if (bond < minimumBond) revert BondTooSmall();
        assertionId = keccak256(abi.encode(claim, asserter, block.timestamp, _nonce++));

        if (!currency.transferFrom(msg.sender, address(this), bond)) revert TransferFailed();

        _assertions[assertionId] = Assertion({
            claim: claim,
            asserter: asserter,
            callbackRecipient: callbackRecipient,
            disputer: address(0),
            currency: currency,
            bond: bond,
            expiresAt: uint64(block.timestamp) + liveness,
            settled: false,
            resolvedTruthful: false,
            voteCast: false,
            voteTruthful: false
        });

        emit AssertionMade(assertionId, asserter, _assertions[assertionId].expiresAt);
    }

    function disputeAssertion(bytes32 assertionId, address disputer) external {
        Assertion storage a = _assertions[assertionId];
        if (a.asserter == address(0)) revert UnknownAssertion();
        if (a.settled) revert AlreadySettled();
        if (a.disputer != address(0)) revert AlreadyDisputed();
        if (block.timestamp > a.expiresAt) revert DisputeWindowClosed();

        a.disputer = disputer;
        if (!a.currency.transferFrom(msg.sender, address(this), a.bond)) revert TransferFailed();

        emit AssertionDisputed(assertionId, disputer);
        if (a.callbackRecipient != address(0)) {
            IOptimisticOracleV3CallbackRecipient(a.callbackRecipient).assertionDisputedCallback(assertionId);
        }
    }

    /// @notice Stands in for a DVM vote on a disputed assertion.
    function resolveDispute(bytes32 assertionId, bool truthful) external {
        if (msg.sender != voter) revert NotVoter();
        Assertion storage a = _assertions[assertionId];
        if (a.asserter == address(0)) revert UnknownAssertion();
        if (a.disputer == address(0)) revert UnknownAssertion();
        if (a.settled) revert AlreadySettled();
        a.voteCast = true;
        a.voteTruthful = truthful;
    }

    function settleAndGetAssertionResult(bytes32 assertionId) external returns (bool) {
        Assertion storage a = _assertions[assertionId];
        if (a.asserter == address(0)) revert UnknownAssertion();
        if (a.settled) return a.resolvedTruthful;

        bool truthful;
        address winner;
        if (a.disputer == address(0)) {
            if (block.timestamp <= a.expiresAt) revert StillLive();
            truthful = true;
            winner = a.asserter;
        } else {
            if (!a.voteCast) revert AwaitingVote();
            truthful = a.voteTruthful;
            winner = truthful ? a.asserter : a.disputer;
        }

        a.settled = true;
        a.resolvedTruthful = truthful;

        // The real oracle burns a slice of the loser's bond; paying the whole pot keeps
        // the mock's accounting trivial without changing who wins.
        uint256 pot = a.disputer == address(0) ? a.bond : a.bond * 2;
        if (!a.currency.transfer(winner, pot)) revert TransferFailed();

        emit AssertionResolved(assertionId, truthful);
        if (a.callbackRecipient != address(0)) {
            IOptimisticOracleV3CallbackRecipient(a.callbackRecipient).assertionResolvedCallback(assertionId, truthful);
        }
        return truthful;
    }

    function getAssertionResult(bytes32 assertionId) external view returns (bool) {
        Assertion storage a = _assertions[assertionId];
        if (!a.settled) revert AwaitingVote();
        return a.resolvedTruthful;
    }

    function getAssertion(bytes32 assertionId) external view returns (Assertion memory) {
        return _assertions[assertionId];
    }
}

MockPriceSources.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// Stand-ins for the price sources PriceLens reads, shaped exactly like the real
// ones at the call sites the lens uses. They exist so the lens can be exercised on
// a chain that has no Chainlink and no Uniswap — a dev chain, or the in-process EVM
// in contracts/evmtest — through the same eth_call path production takes.
//
// Nothing here is for a real network. Every setter is open.

/// @notice Chainlink AggregatorV3Interface, with a knob.
contract MockAggregatorV3 {
    uint8 public immutable decimals;
    string public description;
    uint256 public constant version = 4;

    uint80 private _roundId;
    int256 private _answer;
    uint256 private _startedAt;
    uint256 private _updatedAt;

    constructor(uint8 decimals_, string memory description_, int256 answer_) {
        decimals = decimals_;
        description = description_;
        _set(answer_, block.timestamp);
    }

    /// @notice Post a new round, timestamped now.
    function setAnswer(int256 answer_) external {
        _set(answer_, block.timestamp);
    }

    /// @notice Post a round with an explicit timestamp, to fake a stale feed.
    function setAnswerAt(int256 answer_, uint256 updatedAt_) external {
        _set(answer_, updatedAt_);
    }

    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        return (_roundId, _answer, _startedAt, _updatedAt, _roundId);
    }

    function _set(int256 answer_, uint256 at) private {
        _roundId++;
        _answer = answer_;
        _startedAt = at;
        _updatedAt = at;
    }
}

/// @notice Chainlink Feed Registry: `getFeed(base, quote)`, reverting when unset, as
///         the real one does.
contract MockFeedRegistry {
    mapping(address => mapping(address => address)) private _feeds;

    error FeedNotFound();

    function setFeed(address base, address quote, address aggregator) external {
        _feeds[base][quote] = aggregator;
    }

    function getFeed(address base, address quote) external view returns (address) {
        address a = _feeds[base][quote];
        if (a == address(0)) revert FeedNotFound();
        return a;
    }
}

/// @notice Uniswap v3 factory surface: `getPool` for whatever pools were registered,
///         in either token order, as the real factory does.
contract MockUniswapV3Factory {
    mapping(address => mapping(address => mapping(uint24 => address))) public getPool;

    function register(address pool) external {
        MockUniswapV3Pool p = MockUniswapV3Pool(pool);
        (address t0, address t1, uint24 fee) = (p.token0(), p.token1(), p.fee());
        getPool[t0][t1][fee] = pool;
        getPool[t1][t0][fee] = pool;
    }
}

/// @notice The slice of a Uniswap v3 pool the lens reads: slot0, liquidity, the
///         observation ring buffer, and observe().
///
/// The oracle is modelled as "the tick has been constant since `since`": the
/// cumulative at time T is tick * T, so any window the lens asks for averages back
/// to exactly `tick`. Spot and TWAP are set independently so a test can make them
/// disagree.
contract MockUniswapV3Pool {
    address public immutable token0;
    address public immutable token1;
    uint24 public immutable fee;

    uint160 public sqrtPriceX96;
    int24 public tick;
    uint128 public liquidity;
    /// @dev Oldest observation the "ring buffer" holds. Windows longer than
    ///      block.timestamp - since are not observable, as on a real pool.
    uint32 public since;
    uint16 private _cardinality;

    error OLD();

    constructor(address token0_, address token1_, uint24 fee_, uint160 sqrtPriceX96_, int24 tick_, uint128 liquidity_) {
        require(token0_ < token1_, "token order");
        token0 = token0_;
        token1 = token1_;
        fee = fee_;
        sqrtPriceX96 = sqrtPriceX96_;
        tick = tick_;
        liquidity = liquidity_;
        since = uint32(block.timestamp);
        _cardinality = 1;
    }

    function setState(uint160 sqrtPriceX96_, int24 tick_, uint128 liquidity_) external {
        sqrtPriceX96 = sqrtPriceX96_;
        tick = tick_;
        liquidity = liquidity_;
    }

    /// @notice Pretend the oracle has history back to `since_`, with `cardinality`
    ///         slots in the buffer (0 models a pool whose oracle was never grown).
    function setHistory(uint32 since_, uint16 cardinality) external {
        since = since_;
        _cardinality = cardinality;
    }

    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96_,
            int24 tick_,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        )
    {
        // Index 0 with cardinality 1 makes the "oldest" slot (index+1) % cardinality
        // == 0, which is initialised: the common case on a pool with a grown buffer
        // is exercised by a larger cardinality, where slot (index+1) is not.
        return (sqrtPriceX96, tick, 0, _cardinality, _cardinality, 0, true);
    }

    function observations(uint256 index)
        external
        view
        returns (uint32 blockTimestamp, int56 tickCumulative, uint160 secondsPerLiquidityCumulativeX128, bool initialized)
    {
        if (index == 0) return (since, int56(tick) * int56(uint56(since)), 0, true);
        return (0, 0, 0, false);
    }

    function observe(uint32[] calldata secondsAgos)
        external
        view
        returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s)
    {
        tickCumulatives = new int56[](secondsAgos.length);
        secondsPerLiquidityCumulativeX128s = new uint160[](secondsAgos.length);
        for (uint256 i = 0; i < secondsAgos.length; i++) {
            uint32 target = uint32(block.timestamp) - secondsAgos[i];
            if (target < since) revert OLD();
            tickCumulatives[i] = int56(tick) * int56(uint56(target));
        }
    }
}

/// @notice Uniswap v2 factory surface: `getPair`, either order.
contract MockUniswapV2Factory {
    mapping(address => mapping(address => address)) public getPair;

    function register(address pair) external {
        MockUniswapV2Pair p = MockUniswapV2Pair(pair);
        (address t0, address t1) = (p.token0(), p.token1());
        getPair[t0][t1] = pair;
        getPair[t1][t0] = pair;
    }
}

/// @notice The slice of a Uniswap v2 pair the lens reads.
contract MockUniswapV2Pair {
    address public immutable token0;
    address public immutable token1;
    uint112 private _reserve0;
    uint112 private _reserve1;
    uint32 private _ts;

    constructor(address token0_, address token1_, uint112 reserve0_, uint112 reserve1_) {
        require(token0_ < token1_, "token order");
        token0 = token0_;
        token1 = token1_;
        _set(reserve0_, reserve1_);
    }

    function setReserves(uint112 reserve0_, uint112 reserve1_) external {
        _set(reserve0_, reserve1_);
    }

    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast) {
        return (_reserve0, _reserve1, _ts);
    }

    function _set(uint112 r0, uint112 r1) private {
        _reserve0 = r0;
        _reserve1 = r1;
        _ts = uint32(block.timestamp);
    }
}

PriceLens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ChainInfo} from "./AssetLens.sol";

// ---------------------------------------------------------------------------
// Wire types
//
// File-level, like AssetLens: the lens and the ABI-carrier interface both name
// them without inheritance putting runtime code into the lens.
// ---------------------------------------------------------------------------

/// @notice An explicit token -> Chainlink aggregator binding, for chains with no
///         Feed Registry or for feeds the operator wants to pin.
struct FeedHint {
    address token;
    /// @dev An AggregatorV3Interface (a Chainlink proxy, usually).
    address aggregator;
    /// @dev 0 = quoted in USD, 1 = quoted in the chain's native asset.
    uint8 quote;
}

/// @notice Everything one price read needs. Encoded as the constructor argument.
struct PriceRequest {
    /// @dev Tokens to price. Quote tokens the caller wants to route through must be
    ///      in here too: the lens prices each address independently and leaves the
    ///      routing (token -> WETH -> USD) to the client.
    address[] tokens;
    /// @dev Chainlink Feed Registry, or zero. Mainnet has one; most chains do not.
    address feedRegistry;
    /// @dev Aggregator for the native asset in USD (ETH/USD on Ethereum), or zero
    ///      to let the registry resolve it.
    address nativeUsdFeed;
    FeedHint[] feeds;
    /// @dev Uniswap v3 factory (or any getPool-compatible fork), or zero.
    address v3Factory;
    /// @dev Fee tiers to probe. Empty uses 100 / 500 / 3000 / 10000.
    uint24[] feeTiers;
    /// @dev Uniswap v2 factory (or any getPair-compatible fork), or zero.
    address v2Factory;
    /// @dev Pool counterparties to look for: the wrapped native asset and the
    ///      major stables. A token is priced against each of these it has a pool with.
    address[] quoteTokens;
    /// @dev Requested TWAP window in seconds. The lens reports the window it could
    ///      actually get from each pool's oracle, which may be shorter.
    uint32 twapWindow;
    /// @dev Gas ceiling per external call. 0 uses DEFAULT_CALL_GAS.
    uint256 gasPerCall;
    /// @dev Cap on every returned string. 0 uses DEFAULT_STRING_BYTES.
    uint256 maxStringBytes;
}

/// @notice One Chainlink-shaped feed, read once.
///
/// Nothing here is interpreted: the client decides what "stale" means and whether
/// an answer of zero is a price or a broken feed. The lens only reports what the
/// aggregator said and when it said it.
struct FeedInfo {
    address aggregator;
    /// @dev 0 USD, 1 native.
    uint8 quote;
    /// @dev Resolved through the Feed Registry rather than named by the caller.
    bool viaRegistry;
    /// @dev latestRoundData answered with a well-formed tuple.
    bool ok;
    int256 answer;
    uint8 decimals;
    bool hasDecimals;
    uint256 startedAt;
    uint256 updatedAt;
    uint80 roundId;
    uint80 answeredInRound;
    string description;
}

/// @notice One DEX pool holding the token against one of the quote tokens.
///
/// Raw observations only. Turning a tick into a price is arithmetic the client can
/// do exactly, and keeping it out of here keeps this contract small enough to ship
/// with every call.
struct PoolInfo {
    address pool;
    /// @dev 3 = Uniswap v3-style (concentrated liquidity, tick oracle),
    ///      2 = Uniswap v2-style (constant product, reserves only).
    uint8 kind;
    address token0;
    address token1;
    uint24 fee;
    // v3
    uint160 sqrtPriceX96;
    int24 tick;
    uint128 liquidity;
    /// @dev The TWAP window actually observed, in seconds. Zero when the pool's
    ///      oracle held no history to average over, in which case only the spot
    ///      price above is available and the client should say so.
    uint32 twapWindow;
    int56 tickCumulativeStart;
    int56 tickCumulativeEnd;
    // v2
    uint112 reserve0;
    uint112 reserve1;
    uint32 reserveTimestamp;
}

/// @notice Every price source the lens found for one token.
struct TokenPrices {
    address token;
    bool isContract;
    string symbol;
    uint8 decimals;
    bool hasDecimals;
    FeedInfo[] feeds;
    PoolInfo[] pools;
}

struct PriceResult {
    ChainInfo chain;
    /// @dev The native asset in USD. Everything quoted in ETH or routed through the
    ///      wrapped native token crosses through this one read.
    FeedInfo native;
    TokenPrices[] tokens;
}

/// @notice ABI carrier for the deployless reply, same trick as IAssetLens.
interface IPriceLens {
    function query(PriceRequest calldata req) external view returns (PriceResult memory res);
}

/// @title PriceLens
/// @notice Discovers and reads on-chain price sources for a set of tokens in a
///         single call, without being deployed.
///
/// ## What "price discovery" means here
///
/// evm-scan reads public state from your own node and asks nobody's permission. A
/// price is no different, as long as it comes from the chain rather than from a
/// quote API: Chainlink aggregators and DEX pools are contracts, and a snap-synced
/// node can read both at the head. The problem is finding them. For a token nobody
/// configured, this lens asks the chain itself:
///
///   1. the Chainlink Feed Registry, if the chain has one (mainnet does) —
///      `getFeed(token, USD)` and `getFeed(token, ETH)`;
///   2. any aggregator the operator pinned for the token;
///   3. every Uniswap v3 pool between the token and each quote token at each
///      fee tier, with the pool's own TWAP oracle read over the requested window;
///   4. every Uniswap v2 pair between the token and each quote token.
///
/// It returns all of them, raw, and the client picks: a fresh feed beats a TWAP
/// beats a spot, and a spot is labelled as the manipulable number it is.
///
/// ## Deployless, like AssetLens
///
/// The constructor returns `abi.encode(PriceResult)` and the client sends the
/// creation code as an `eth_call` with no `to`. Same limits (EIP-170 on the reply,
/// EIP-3860 on the payload), same batching on the client side, same posture: no
/// deployment, no address to trust, works on any chain the moment it compiles.
///
/// ## Reading hostile contracts
///
/// A factory, a pool or a feed is somebody else's code. Every read is a bounded
/// staticcall with capped gas and capped returndata; a source that reverts, lies
/// about its return shape or burns gas costs its own slot in the reply and nothing
/// else. Nothing a pool does can take the batch down.
contract PriceLens {
    // Chainlink AggregatorV3Interface + FeedRegistryInterface.
    bytes4 private constant SEL_LATEST_ROUND_DATA = bytes4(keccak256("latestRoundData()"));
    bytes4 private constant SEL_DECIMALS = bytes4(keccak256("decimals()"));
    bytes4 private constant SEL_DESCRIPTION = bytes4(keccak256("description()"));
    bytes4 private constant SEL_GET_FEED = bytes4(keccak256("getFeed(address,address)"));
    bytes4 private constant SEL_SYMBOL = bytes4(keccak256("symbol()"));

    // Uniswap v3 factory + pool.
    bytes4 private constant SEL_GET_POOL = bytes4(keccak256("getPool(address,address,uint24)"));
    bytes4 private constant SEL_TOKEN0 = bytes4(keccak256("token0()"));
    bytes4 private constant SEL_TOKEN1 = bytes4(keccak256("token1()"));
    bytes4 private constant SEL_LIQUIDITY = bytes4(keccak256("liquidity()"));
    bytes4 private constant SEL_SLOT0 = bytes4(keccak256("slot0()"));
    bytes4 private constant SEL_OBSERVATIONS = bytes4(keccak256("observations(uint256)"));
    bytes4 private constant SEL_OBSERVE = bytes4(keccak256("observe(uint32[])"));

    // Uniswap v2 factory + pair.
    bytes4 private constant SEL_GET_PAIR = bytes4(keccak256("getPair(address,address)"));
    bytes4 private constant SEL_GET_RESERVES = bytes4(keccak256("getReserves()"));

    /// @dev Chainlink's denomination sentinels, as the Feed Registry keys them.
    ///      USD is ISO 4217 code 840; ETH is the conventional 0xEeee… address.
    address private constant DENOM_USD = address(840);
    address private constant DENOM_ETH = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    uint8 private constant QUOTE_USD = 0;
    uint8 private constant QUOTE_NATIVE = 1;
    uint8 private constant KIND_V2 = 2;
    uint8 private constant KIND_V3 = 3;

    uint256 private constant DEFAULT_CALL_GAS = 250_000;
    uint256 private constant DEFAULT_STRING_BYTES = 64;
    uint256 private constant MAX_STRING_BYTES = 256;
    uint256 private constant MAX_RETURN_BYTES = 1024;
    /// @dev Bounds the per-token pool sweep: quote tokens × (fee tiers + 1 v2 pair).
    uint256 private constant MAX_QUOTE_TOKENS = 8;
    uint256 private constant MAX_FEE_TIERS = 6;

    struct Ctx {
        address feedRegistry;
        FeedHint[] feeds;
        address v3Factory;
        uint24[] feeTiers;
        address v2Factory;
        address[] quoteTokens;
        uint32 twapWindow;
        uint256 gasPerCall;
        uint256 cap;
    }

    /// @notice Runs the query and returns `abi.encode(PriceResult)` as the "deployed code".
    constructor(PriceRequest memory req) {
        bytes memory out = abi.encode(_run(req));
        assembly {
            return(add(out, 0x20), mload(out))
        }
    }

    // ----------------------------------------------------------------------
    // Query
    // ----------------------------------------------------------------------

    function _run(PriceRequest memory req) private view returns (PriceResult memory res) {
        res.chain = ChainInfo({
            chainId: block.chainid,
            blockNumber: block.number,
            parentHash: block.number == 0 ? bytes32(0) : blockhash(block.number - 1),
            timestamp: block.timestamp,
            baseFee: block.basefee
        });

        uint256 cap = req.maxStringBytes == 0 ? DEFAULT_STRING_BYTES : req.maxStringBytes;
        Ctx memory c = Ctx({
            feedRegistry: req.feedRegistry,
            feeds: req.feeds,
            v3Factory: req.v3Factory,
            feeTiers: req.feeTiers.length == 0 ? _defaultFeeTiers() : _clipTiers(req.feeTiers),
            v2Factory: req.v2Factory,
            quoteTokens: _clipQuotes(req.quoteTokens),
            twapWindow: req.twapWindow,
            gasPerCall: req.gasPerCall == 0 ? DEFAULT_CALL_GAS : req.gasPerCall,
            cap: cap > MAX_STRING_BYTES ? MAX_STRING_BYTES : cap
        });

        // The native asset: an explicit feed wins, the registry's ETH/USD is the
        // fallback. Without either the reply says so with aggregator == 0.
        if (req.nativeUsdFeed != address(0)) {
            res.native = _readFeed(req.nativeUsdFeed, QUOTE_USD, false, c);
        } else if (c.feedRegistry != address(0)) {
            address agg = _getFeed(c.feedRegistry, DENOM_ETH, DENOM_USD, c.gasPerCall);
            if (agg != address(0)) res.native = _readFeed(agg, QUOTE_USD, true, c);
        }

        res.tokens = new TokenPrices[](req.tokens.length);
        for (uint256 i = 0; i < req.tokens.length; i++) {
            res.tokens[i] = _token(req.tokens[i], c);
        }
    }

    function _token(address token, Ctx memory c) private view returns (TokenPrices memory t) {
        t.token = token;
        t.isContract = _codeSize(token) > 0;
        t.feeds = new FeedInfo[](0);
        t.pools = new PoolInfo[](0);
        if (!t.isContract) return t;

        (bool okSym, bytes memory rSym) = _call(token, abi.encodeWithSelector(SEL_SYMBOL), c.gasPerCall);
        if (okSym) t.symbol = _string(rSym, c.cap);
        (t.decimals, t.hasDecimals) = _decimals(token, c.gasPerCall);

        t.feeds = _feeds(token, c);
        t.pools = _pools(token, c);
    }

    // ----------------------------------------------------------------------
    // Chainlink
    // ----------------------------------------------------------------------

    /// @dev Explicit hints first, then whatever the registry knows for the quotes the
    ///      hints did not cover. Two explicit hints for the same quote both come back;
    ///      choosing between them is the client's job.
    function _feeds(address token, Ctx memory c) private view returns (FeedInfo[] memory out) {
        FeedInfo[] memory buf = new FeedInfo[](c.feeds.length + 2);
        uint256 n;
        bool haveUsd;
        bool haveNative;

        for (uint256 i = 0; i < c.feeds.length; i++) {
            if (c.feeds[i].token != token) continue;
            uint8 q = c.feeds[i].quote == QUOTE_NATIVE ? QUOTE_NATIVE : QUOTE_USD;
            buf[n++] = _readFeed(c.feeds[i].aggregator, q, false, c);
            if (q == QUOTE_USD) haveUsd = true;
            else haveNative = true;
        }

        if (c.feedRegistry != address(0)) {
            if (!haveUsd) {
                address agg = _getFeed(c.feedRegistry, token, DENOM_USD, c.gasPerCall);
                if (agg != address(0)) buf[n++] = _readFeed(agg, QUOTE_USD, true, c);
            }
            if (!haveNative) {
                address agg = _getFeed(c.feedRegistry, token, DENOM_ETH, c.gasPerCall);
                if (agg != address(0)) buf[n++] = _readFeed(agg, QUOTE_NATIVE, true, c);
            }
        }

        out = new FeedInfo[](n);
        for (uint256 i = 0; i < n; i++) {
            out[i] = buf[i];
        }
    }

    /// @dev FeedRegistry.getFeed reverts when no feed exists, which the bounded call
    ///      turns into "zero address" rather than into a failed batch.
    function _getFeed(address registry, address base, address quote, uint256 gasPerCall)
        private
        view
        returns (address)
    {
        (bool ok, bytes memory r) =
            _call(registry, abi.encodeWithSelector(SEL_GET_FEED, base, quote), gasPerCall);
        if (!ok) return address(0);
        (uint256 v, bool okv) = _word(r, 0);
        return okv ? address(uint160(v)) : address(0);
    }

    function _readFeed(address agg, uint8 quote, bool viaRegistry, Ctx memory c)
        private
        view
        returns (FeedInfo memory f)
    {
        f.aggregator = agg;
        f.quote = quote;
        f.viaRegistry = viaRegistry;
        if (_codeSize(agg) == 0) return f;

        (bool ok, bytes memory r) = _call(agg, abi.encodeWithSelector(SEL_LATEST_ROUND_DATA), c.gasPerCall);
        if (ok && r.length >= 160) {
            (uint256 w0,) = _word(r, 0);
            (uint256 w1,) = _word(r, 1);
            (uint256 w2,) = _word(r, 2);
            (uint256 w3,) = _word(r, 3);
            (uint256 w4,) = _word(r, 4);
            f.roundId = uint80(w0);
            f.answer = int256(w1);
            f.startedAt = w2;
            f.updatedAt = w3;
            f.answeredInRound = uint80(w4);
            f.ok = true;
        }
        (f.decimals, f.hasDecimals) = _decimals(agg, c.gasPerCall);

        (bool okD, bytes memory rD) = _call(agg, abi.encodeWithSelector(SEL_DESCRIPTION), c.gasPerCall);
        if (okD) f.description = _string(rD, c.cap);
    }

    // ----------------------------------------------------------------------
    // DEX pools
    // ----------------------------------------------------------------------

    /// @dev Every (quote token, fee tier) v3 pool and every v2 pair that exists and
    ///      holds liquidity. Empty pools are dropped here rather than reported: a
    ///      tick with no liquidity behind it is not a price, and the reply has to
    ///      fit in 24KB.
    function _pools(address token, Ctx memory c) private view returns (PoolInfo[] memory out) {
        uint256 perQuote = (c.v3Factory == address(0) ? 0 : c.feeTiers.length) + (c.v2Factory == address(0) ? 0 : 1);
        PoolInfo[] memory buf = new PoolInfo[](c.quoteTokens.length * perQuote);
        uint256 n;

        for (uint256 q = 0; q < c.quoteTokens.length; q++) {
            address quote = c.quoteTokens[q];
            if (quote == token) continue;

            if (c.v3Factory != address(0)) {
                for (uint256 f = 0; f < c.feeTiers.length; f++) {
                    address pool = _lookup(
                        c.v3Factory, abi.encodeWithSelector(SEL_GET_POOL, token, quote, c.feeTiers[f]), c.gasPerCall
                    );
                    if (pool == address(0)) continue;
                    PoolInfo memory p = _readV3(pool, c.feeTiers[f], c);
                    if (_usable(p, token, quote)) buf[n++] = p;
                }
            }
            if (c.v2Factory != address(0)) {
                address pair = _lookup(c.v2Factory, abi.encodeWithSelector(SEL_GET_PAIR, token, quote), c.gasPerCall);
                if (pair != address(0)) {
                    PoolInfo memory p = _readV2(pair, c.gasPerCall);
                    if (_usable(p, token, quote)) buf[n++] = p;
                }
            }
        }

        out = new PoolInfo[](n);
        for (uint256 i = 0; i < n; i++) {
            out[i] = buf[i];
        }
    }

    /// @dev A pool is only reported when it really is between the token and the
    ///      quote (a factory that hands back an unrelated address is lying) and
    ///      when there is something in it.
    function _usable(PoolInfo memory p, address token, address quote) private pure returns (bool) {
        bool pair = (p.token0 == token && p.token1 == quote) || (p.token0 == quote && p.token1 == token);
        if (!pair) return false;
        if (p.kind == KIND_V3) return p.liquidity > 0 && p.sqrtPriceX96 > 0;
        return p.reserve0 > 0 && p.reserve1 > 0;
    }

    function _lookup(address factory, bytes memory data, uint256 gasPerCall) private view returns (address) {
        (bool ok, bytes memory r) = _call(factory, data, gasPerCall);
        if (!ok) return address(0);
        (uint256 v, bool okv) = _word(r, 0);
        if (!okv) return address(0);
        address a = address(uint160(v));
        return _codeSize(a) > 0 ? a : address(0);
    }

    function _readV3(address pool, uint24 fee, Ctx memory c) private view returns (PoolInfo memory p) {
        p.pool = pool;
        p.kind = KIND_V3;
        p.fee = fee;
        p.token0 = _addressOf(pool, SEL_TOKEN0, c.gasPerCall);
        p.token1 = _addressOf(pool, SEL_TOKEN1, c.gasPerCall);

        (bool okL, bytes memory rL) = _call(pool, abi.encodeWithSelector(SEL_LIQUIDITY), c.gasPerCall);
        if (okL) {
            (uint256 l,) = _word(rL, 0);
            p.liquidity = uint128(l);
        }

        (bool ok, bytes memory r) = _call(pool, abi.encodeWithSelector(SEL_SLOT0), c.gasPerCall);
        if (!ok || r.length < 224) return p;
        (uint256 w0,) = _word(r, 0);
        (uint256 w1,) = _word(r, 1);
        (uint256 w2,) = _word(r, 2);
        (uint256 w3,) = _word(r, 3);
        p.sqrtPriceX96 = uint160(w0);
        p.tick = int24(int256(w1));
        uint16 index = uint16(w2);
        uint16 cardinality = uint16(w3);

        if (c.twapWindow > 0 && cardinality > 0) {
            _twap(p, index, cardinality, c);
        }
    }

    /// @dev The pool's oracle can only average over the history it kept. Find the
    ///      oldest observation the ring buffer still holds, clamp the window to it,
    ///      and read the cumulatives at both ends. A pool whose oldest observation
    ///      is the current block yields no window at all, and says so with 0.
    function _twap(PoolInfo memory p, uint16 index, uint16 cardinality, Ctx memory c) private view {
        (uint32 oldestTs, bool okTs) = _oldestObservation(p.pool, index, cardinality, c.gasPerCall);
        if (!okTs) return;

        uint32 age;
        unchecked {
            age = uint32(block.timestamp) - oldestTs;
        }
        uint32 window = c.twapWindow < age ? c.twapWindow : age;
        if (window == 0) return;

        (int56 c0, int56 c1, bool ok) = _observe(p.pool, window, c.gasPerCall);
        if (!ok) return;
        p.twapWindow = window;
        p.tickCumulativeStart = c0;
        p.tickCumulativeEnd = c1;
    }

    /// @dev Timestamp of the oldest observation in the ring buffer: the slot after
    ///      the current one once the buffer has wrapped, slot 0 until then.
    function _oldestObservation(address pool, uint16 index, uint16 cardinality, uint256 gasPerCall)
        private
        view
        returns (uint32 ts, bool ok)
    {
        uint256 oldest = (uint256(index) + 1) % cardinality;
        (bool okCall, bytes memory r) = _call(pool, abi.encodeWithSelector(SEL_OBSERVATIONS, oldest), gasPerCall);
        if (!okCall || r.length < 128) return (0, false);
        (uint256 w0,) = _word(r, 0);
        (uint256 initialized,) = _word(r, 3);
        if (initialized != 0) return (uint32(w0), true);

        (okCall, r) = _call(pool, abi.encodeWithSelector(SEL_OBSERVATIONS, uint256(0)), gasPerCall);
        if (!okCall || r.length < 128) return (0, false);
        (w0,) = _word(r, 0);
        return (uint32(w0), true);
    }

    /// @dev observe([window, 0]) decoded tolerantly: the reply is
    ///      (int56[] tickCumulatives, uint160[] secondsPerLiquidityCumulativeX128s),
    ///      and only the first array's two members are wanted.
    function _observe(address pool, uint32 window, uint256 gasPerCall)
        private
        view
        returns (int56 c0, int56 c1, bool ok)
    {
        uint32[] memory ago = new uint32[](2);
        ago[0] = window;
        ago[1] = 0;
        (bool okCall, bytes memory r) = _call(pool, abi.encodeWithSelector(SEL_OBSERVE, ago), gasPerCall);
        if (!okCall) return (0, 0, false);

        (uint256 off, bool okOff) = _word(r, 0);
        if (!okOff || off % 32 != 0 || off + 96 > r.length) return (0, 0, false);
        (uint256 len,) = _word(r, off / 32);
        if (len < 2) return (0, 0, false);
        (uint256 w1,) = _word(r, off / 32 + 1);
        (uint256 w2,) = _word(r, off / 32 + 2);
        return (int56(int256(w1)), int56(int256(w2)), true);
    }

    function _readV2(address pair, uint256 gasPerCall) private view returns (PoolInfo memory p) {
        p.pool = pair;
        p.kind = KIND_V2;
        p.token0 = _addressOf(pair, SEL_TOKEN0, gasPerCall);
        p.token1 = _addressOf(pair, SEL_TOKEN1, gasPerCall);

        (bool ok, bytes memory r) = _call(pair, abi.encodeWithSelector(SEL_GET_RESERVES), gasPerCall);
        if (!ok || r.length < 96) return p;
        (uint256 w0,) = _word(r, 0);
        (uint256 w1,) = _word(r, 1);
        (uint256 w2,) = _word(r, 2);
        p.reserve0 = uint112(w0);
        p.reserve1 = uint112(w1);
        p.reserveTimestamp = uint32(w2);
    }

    // ----------------------------------------------------------------------
    // Request normalisation
    // ----------------------------------------------------------------------

    function _defaultFeeTiers() private pure returns (uint24[] memory tiers) {
        tiers = new uint24[](4);
        tiers[0] = 100;
        tiers[1] = 500;
        tiers[2] = 3000;
        tiers[3] = 10000;
    }

    function _clipTiers(uint24[] memory tiers) private pure returns (uint24[] memory) {
        if (tiers.length <= MAX_FEE_TIERS) return tiers;
        uint24[] memory out = new uint24[](MAX_FEE_TIERS);
        for (uint256 i = 0; i < MAX_FEE_TIERS; i++) {
            out[i] = tiers[i];
        }
        return out;
    }

    function _clipQuotes(address[] memory quotes) private pure returns (address[] memory) {
        if (quotes.length <= MAX_QUOTE_TOKENS) return quotes;
        address[] memory out = new address[](MAX_QUOTE_TOKENS);
        for (uint256 i = 0; i < MAX_QUOTE_TOKENS; i++) {
            out[i] = quotes[i];
        }
        return out;
    }

    // ----------------------------------------------------------------------
    // Bounded calls and tolerant decoding
    // ----------------------------------------------------------------------

    function _codeSize(address a) private view returns (uint256 size) {
        assembly ("memory-safe") {
            size := extcodesize(a)
        }
    }

    function _decimals(address target, uint256 gasPerCall) private view returns (uint8 d, bool ok) {
        (bool okCall, bytes memory r) = _call(target, abi.encodeWithSelector(SEL_DECIMALS), gasPerCall);
        if (!okCall) return (0, false);
        (uint256 v, bool okv) = _word(r, 0);
        // Nothing honest scales by more than 10**77; anything above is garbage.
        if (!okv || v > 77) return (0, false);
        return (uint8(v), true);
    }

    function _addressOf(address target, bytes4 sel, uint256 gasPerCall) private view returns (address) {
        (bool ok, bytes memory r) = _call(target, abi.encodeWithSelector(sel), gasPerCall);
        if (!ok) return address(0);
        (uint256 v, bool okv) = _word(r, 0);
        return okv ? address(uint160(v)) : address(0);
    }

    /// @dev staticcall with capped gas and capped returndata copy. Never reverts.
    function _call(address target, bytes memory data, uint256 gasLimit)
        private
        view
        returns (bool ok, bytes memory ret)
    {
        uint256 maxReturn = MAX_RETURN_BYTES;
        assembly {
            ok := staticcall(gasLimit, target, add(data, 0x20), mload(data), 0, 0)
            let size := returndatasize()
            if gt(size, maxReturn) { size := maxReturn }
            ret := mload(0x40)
            mstore(ret, size)
            returndatacopy(add(ret, 0x20), 0, size)
            mstore(0x40, add(ret, and(add(add(size, 0x20), 0x1f), not(0x1f))))
        }
    }

    /// @dev Word `i` of a return buffer, or (0, false) when the buffer is too short.
    function _word(bytes memory ret, uint256 i) private pure returns (uint256 v, bool ok) {
        if (ret.length < 32 * (i + 1)) return (0, false);
        assembly {
            v := mload(add(add(ret, 0x20), mul(i, 32)))
        }
        ok = true;
    }

    /// @dev ABI string or legacy bytes32, truncated to `cap`, offsets never trusted.
    function _string(bytes memory ret, uint256 cap) private pure returns (string memory s) {
        if (ret.length == 32) {
            uint256 n;
            while (n < 32 && ret[n] != 0) {
                n++;
            }
            if (n > cap) n = cap;
            bytes memory b = new bytes(n);
            for (uint256 i = 0; i < n; i++) {
                b[i] = ret[i];
            }
            return string(b);
        }
